<script setup lang="ts">
import { computed, defineAsyncComponent, ref } from 'vue'
import AgentAvatar from './AgentAvatar.vue'
import Icon from './StudioIcon.vue'
import ExportDialog from './ExportDialog.vue'
import { ACCESSORIES, BODY_SHAPES, MOODS, MOTIONS, type AgentConfig } from './catalog'
import { useStudio } from './useStudio'
import { download, renderAnimatedSvg } from './export'

const { project, selected, config, time, playing, sequencing, duration, scene, dirty, message, reduced, notify, patch, toggleAccessory, save, duplicate, resetAgent, setMotion, addScene, updateScene, removeScene, moveScene, seekScene, importFile } = useStudio()
const tab = ref<'design' | 'animation' | 'integration'>('design')
const propertyTab = ref<'appearance' | 'accessories'>('appearance')
const exporting = ref(false)
const presenting = ref(false)
const AgentPresentation = defineAsyncComponent(() => import('./presentation/AgentPresentation.vue'))
const grid = ref(true)
const dark = ref(false)
const team = ref(false)
const zoom = ref(100)
const inputFile = ref<HTMLInputElement>()
const bodyColors = ['#111112', '#364152', '#735448', '#f9ede2', '#377c61', '#6250a2']
const accentColors = ['#ff5d22', '#eab84c', '#77a985', '#7f9fd4', '#a48fc7', '#ec8ca1']
const currentMotion = computed(() => MOTIONS.find(m => m.id === scene.value.state)!)
const timelineDuration = computed(() => project.value.timeline.reduce((sum, block) => sum + block.duration, 0))
const integrationCode = computed(() => `<script setup lang="ts">\nimport AgentAvatar from './agents/AgentAvatar.vue'\nimport { parseProject } from './agents/catalog'\nimport json from './qamarero-agents.json'\n\nconst project = parseProject(json)\nconst agent = project.agents.find(\n  a => a.id === '${config.value.id}'\n)!\n<\/script>\n\n<template>\n  <AgentAvatar\n    :config="agent"\n    state="${scene.value.state}"\n    :size="160"\n    :playing="true"\n  />\n</template>`)
function numberPatch(key: keyof AgentConfig, event: Event) { patch({ [key]: Number((event.target as HTMLInputElement).value) }) }
function downloadProject() { download(new Blob([JSON.stringify(project.value, null, 2)], { type: 'application/json' }), 'qamarero-agents.json'); notify('Proyecto JSON exportado con agentes y secuencia.') }
async function copyCode() {
  try { await navigator.clipboard.writeText(integrationCode.value); notify('Código copiado.') }
  catch { notify('No se pudo acceder al portapapeles. Selecciona y copia el código.') }
}
function downloadAnimation() { download(new Blob([renderAnimatedSvg(config.value, scene.value.state)], { type: 'image/svg+xml' }), `${config.value.id}-animated.svg`) }
function chooseAgent(id: string) { selected.value = id }
function sceneDuration(index: number, event: Event) {
  const value = Number((event.target as HTMLInputElement).value)
  if (Number.isFinite(value)) updateScene(index, { duration: Math.min(10, Math.max(0.5, value)) })
}
</script>

<template>
  <div class="studio-shell">
    <aside class="studio-sidebar">
      <a class="brand" href="#" aria-label="Qamarero Agent Studio"><span class="brand-symbol">q<span></span></span><span>qamarero<span class="brand-label">agent studio</span></span></a>
      <div class="workspace-label"><span class="workspace-icon">Q</span><div>Espacio de Qamarero<small>Un equipo con personalidad</small></div><Icon name="down" :size="15" /></div>
      <div class="side-section-label">TU ESPACIO</div>
      <nav aria-label="Estudio"><button :class="['side-link', { active: tab === 'design' }]" @click="tab = 'design'"><Icon name="layers" :size="19" />Mis agentes<span class="count">{{ project.agents.length }}</span></button><button :class="['side-link', { active: tab === 'animation' }]" @click="tab = 'animation'"><Icon name="film" :size="19" />Animaciones<span class="small-dot"></span></button><button :class="['side-link', { active: tab === 'integration' }]" @click="tab = 'integration'"><Icon name="code" :size="19" />Integración</button></nav>
      <div class="side-section-label agents-label">EL EQUIPO <button class="icon-button" aria-label="Crear agente a partir del actual" title="Duplicar agente actual" @click="duplicate"><Icon name="plus" :size="15" /></button></div>
      <div class="agent-list"><button v-for="agent in project.agents" :key="agent.id" :class="['agent-list-item', { selected: selected === agent.id }]" @click="chooseAgent(agent.id)"><span class="agent-mini"><AgentAvatar :config="agent" :time="0.6" :size="43" /></span><span>{{ agent.name }}<small>{{ agent.accessories.length ? ACCESSORIES.filter(a => agent.accessories.includes(a.id)).map(a => a.label).join(' · ') : 'Sin accesorios' }}</small></span><span v-if="selected === agent.id" class="selected-mark"></span></button></div>
      <button class="new-agent" @click="duplicate"><Icon name="plus" :size="17" /> Crear un agente</button>
      <div class="sidebar-bottom"><div class="little-note"><span class="note-spark">✳</span><p>Un mismo equipo.<br /><strong>Infinitas personalidades.</strong></p><span class="note-line"></span></div><a href="https://github.com/IvanCoronado/bloub" target="_blank" rel="noreferrer" class="source-link"><Icon name="github" :size="16" />Hecho sobre bloub<Icon name="external" :size="13" /></a><div class="version-row"><span class="user-badge">Q</span><span>Qamarero Studio<small>Tu laboratorio creativo</small></span><span class="version">v1.0</span></div></div>
    </aside>

    <div class="studio-body">
      <header class="studio-topbar"><div class="breadcrumb">Workspace<Icon name="chevron" :size="13" /><span>{{ tab === 'design' ? 'Mis agentes' : tab === 'animation' ? 'Animaciones' : 'Integración' }}</span></div><div class="topbar-actions"><span class="save-status"><span :class="{ unsaved: dirty }"></span>{{ dirty ? 'Cambios sin guardar' : 'Proyecto local' }}</span><button class="button presentation-entry" @click="playing = false; presenting = true"><Icon name="play" :size="15" />Presentar equipo</button><button class="button save-button" @click="save"><Icon :name="dirty ? 'save' : 'check'" :size="16" />Guardar</button><button class="button primary" @click="playing = false; exporting = true"><Icon name="download" :size="16" />Exportar<Icon name="down" :size="13" /></button></div></header>

      <main class="studio-main">
        <div class="page-heading"><div><div class="eyebrow"><span></span>PERSONALIDAD, PÍXEL A PÍXEL</div><h1>{{ tab === 'integration' ? 'Listos para formar parte.' : 'El equipo cobra vida.' }}</h1><p>Diseña, combina y anima a los agentes de Qamarero.</p></div><button class="text-button import-project" @click="inputFile?.click()"><Icon name="upload" :size="16" />Importar proyecto</button><input ref="inputFile" class="visually-hidden" type="file" accept=".json,application/json" aria-label="Importar proyecto JSON" @change="event => { importFile((event.target as HTMLInputElement).files?.[0]); (event.target as HTMLInputElement).value = '' }" /></div>

        <div v-if="tab !== 'integration'" class="editor-layout">
          <section class="preview-panel" aria-label="Vista previa del agente">
            <div class="preview-toolbar"><div class="document-label"><span class="orange-dot"></span>{{ config.name }}<span class="document-tag">{{ team ? 'Equipo' : 'Agente' }}</span></div><div class="canvas-tools"><button :class="['icon-button', { active: grid }]" aria-label="Mostrar cuadrícula" :aria-pressed="grid" @click="grid = !grid"><Icon name="dotgrid" :size="17" /></button><button :class="['icon-button', { active: dark }]" aria-label="Cambiar fondo" :aria-pressed="dark" @click="dark = !dark"><Icon name="sun" :size="17" /></button><span class="tool-divider"></span><button :class="['icon-button', { active: team }]" aria-label="Ver todo el equipo" :aria-pressed="team" @click="team = !team"><Icon name="users" :size="17" /></button></div></div>
            <div :class="['preview-canvas', { dotted: grid, dark, 'team-view': team }]">
              <span class="canvas-corner">{{ team ? 'EL EQUIPO DE QAMARERO' : 'VISTA PREVIA EN DIRECTO' }}</span>
              <div v-if="team" class="team-stage"><div v-for="agent in project.agents" :key="agent.id" class="team-character"><AgentAvatar :config="agent" :time="scene.time" :state="scene.state" :size="150" /><span>{{ agent.name }}</span></div></div>
              <div v-else class="solo-stage" :style="{ transform: `scale(${zoom / 100})` }"><span class="stage-orbit orbit-one"></span><span class="stage-orbit orbit-two"></span><AgentAvatar :config="config" :time="scene.time" :state="scene.state" :size="350" /></div>
              <div class="canvas-agent-caption" v-if="!team"><span>{{ config.name }}</span><small>{{ config.role }}</small></div>
              <div class="canvas-bottom"><span class="live-state"><span></span>{{ playing ? currentMotion.label : 'En pausa' }}</span><label class="zoom-control"><span class="visually-hidden">Zoom</span><select v-model="zoom"><option :value="75">75 %</option><option :value="100">100 %</option><option :value="125">125 %</option></select></label></div>
            </div>
            <div class="character-strip"><button v-for="agent in project.agents" :key="agent.id" :class="['character-card', { active: selected === agent.id }]" @click="chooseAgent(agent.id)"><AgentAvatar :config="agent" :time="0.6" :size="74" /><span>{{ agent.name }}</span><span v-if="selected === agent.id" class="card-selected"><Icon name="check" :size="10" /></span></button><button class="character-card add-card" aria-label="Añadir agente" @click="duplicate"><Icon name="plus" :size="24" /><span>Crear agente</span></button></div>
          </section>

          <aside class="properties-panel" aria-label="Propiedades del agente">
            <header><div><h2>{{ tab === 'animation' ? 'Movimiento' : 'Hazlo tuyo' }}</h2><p>{{ tab === 'animation' ? 'Una forma de expresarse para cada momento.' : 'Los pequeños detalles marcan el carácter.' }}</p></div><button class="icon-button" aria-label="Restaurar apariencia original" title="Restaurar apariencia" @click="resetAgent"><Icon name="reset" :size="16" /></button></header>
            <template v-if="tab === 'design'">
              <div class="property-tabs"><button :class="{ active: propertyTab === 'appearance' }" @click="propertyTab = 'appearance'">Apariencia</button><button :class="{ active: propertyTab === 'accessories' }" @click="propertyTab = 'accessories'">Accesorios<span>{{ config.accessories.length }}</span></button></div>
              <div v-if="propertyTab === 'appearance'" class="property-content">
                <label class="field-label" for="agent-name">Nombre del agente</label><input id="agent-name" class="text-input" :value="config.name" maxlength="40" @input="event => patch({ name: (event.target as HTMLInputElement).value })" @blur="() => { if (!config.name.trim()) patch({ name: 'Mi agente' }) }" />
                <div class="field-label field-top">Forma del cuerpo<span>5 formas</span></div><div class="shape-picker"><button v-for="shape in BODY_SHAPES" :key="shape.id" :class="{ active: config.shape === shape.id }" :aria-label="shape.label" :aria-pressed="config.shape === shape.id" :title="shape.label" @click="patch({ shape: shape.id })"><span :class="['shape-glyph', shape.id]"></span></button></div>
                <div class="field-label field-top">Color del cuerpo<label class="custom-color" title="Color personalizado del cuerpo">{{ config.bodyColor.toUpperCase() }}<input type="color" :value="config.bodyColor" aria-label="Color personalizado del cuerpo" @input="event => patch({ bodyColor: (event.target as HTMLInputElement).value })" /></label></div><div class="color-picker"><button v-for="color in bodyColors" :key="color" :style="{ background: color }" :class="{ active: config.bodyColor === color }" :aria-label="`Cuerpo ${color}`" :aria-pressed="config.bodyColor === color" @click="patch({ bodyColor: color })"><Icon v-if="config.bodyColor === color" name="check" :size="14" /></button></div>
                <div class="field-label field-top">Color de acento<label class="custom-color" title="Color personalizado de acento">{{ config.accentColor.toUpperCase() }}<input type="color" :value="config.accentColor" aria-label="Color personalizado de acento" @input="event => patch({ accentColor: (event.target as HTMLInputElement).value })" /></label></div><div class="color-picker"><button v-for="color in accentColors" :key="color" :style="{ background: color }" :class="{ active: config.accentColor === color }" :aria-label="`Acento ${color}`" :aria-pressed="config.accentColor === color" @click="patch({ accentColor: color })"><Icon v-if="config.accentColor === color" name="check" :size="14" /></button></div>
                <label class="field-label field-top" for="expression">Expresión de base</label><select id="expression" class="text-input" :value="config.expression" @change="event => patch({ expression: (event.target as HTMLSelectElement).value as AgentConfig['expression'] })"><option v-for="mood in MOODS" :key="mood.id" :value="mood.id">{{ mood.label }}</option></select>
                <label class="field-label field-top" for="depth">Profundidad<span>{{ Math.round(config.depth * 100) }} %</span></label><input id="depth" type="range" min="0" max="1" step="0.01" :value="config.depth" @input="numberPatch('depth', $event)" /><div class="range-extremes"><span>Plano</span><span>Con volumen</span></div>
                <label class="toggle-label shadow-toggle"><span>Sombra suave</span><input type="checkbox" :checked="config.shadow" @change="patch({ shadow: !config.shadow })" /><span class="switch"></span></label>
              </div>
              <div v-else class="property-content accessory-content"><p class="muted">Combina las piezas. Cada accesorio se mueve junto al personaje.</p><button v-for="accessory in ACCESSORIES" :key="accessory.id" :class="['accessory-option', { active: config.accessories.includes(accessory.id) }]" :aria-pressed="config.accessories.includes(accessory.id)" @click="toggleAccessory(accessory.id)"><span class="accessory-icon"><Icon :name="accessory.icon" :size="25" /></span><span>{{ accessory.label }}</span><span class="accessory-check"><Icon v-if="config.accessories.includes(accessory.id)" name="check" :size="13" /><Icon v-else name="plus" :size="13" /></span></button><label class="field-label field-top" for="accessory-scale">Tamaño de accesorios<span>{{ Math.round(config.accessoryScale * 100) }} %</span></label><input id="accessory-scale" type="range" min="0.65" max="1.3" step="0.01" :value="config.accessoryScale" @input="numberPatch('accessoryScale', $event)" /><label class="field-label field-top" for="tilt">Inclinación<span>{{ config.tilt }}°</span></label><input id="tilt" type="range" min="-15" max="15" step="1" :value="config.tilt" @input="numberPatch('tilt', $event)" /></div>
            </template>
            <div v-else class="property-content motion-properties"><button v-for="item in MOTIONS" :key="item.id" :class="['motion-option', { active: scene.state === item.id }]" :aria-pressed="scene.state === item.id" @click="setMotion(item.id)"><span class="motion-icon"><Icon :name="item.icon" :size="19" /></span><span>{{ item.label }}<small>{{ item.description }}</small></span><span v-if="scene.state === item.id" class="orange-dot"></span></button><label class="field-label field-top" for="intensity">Intensidad<span>{{ Math.round(config.intensity * 100) }} %</span></label><input id="intensity" type="range" min="0" max="1" step="0.01" :value="config.intensity" @input="numberPatch('intensity', $event)" /><label class="field-label field-top" for="speed">Velocidad<span>{{ config.speed }}×</span></label><input id="speed" type="range" min="0.25" max="2" step="0.05" :value="config.speed" @input="numberPatch('speed', $event)" /><button class="button full-width" @click="addScene(scene.state)"><Icon name="plus" :size="15" />Añadir estado a la secuencia</button></div>
            <footer class="properties-footer"><Icon name="sparkles" :size="15" /><span>{{ propertyTab === 'accessories' && tab === 'design' ? 'Las mejores ideas surgen combinando.' : 'Diseñado para tener personalidad.' }}</span></footer>
          </aside>

          <section class="timeline-panel" aria-label="Secuencia de animación"><div class="timeline-heading"><div><Icon name="film" :size="17" /><h2>Un poco de movimiento</h2><span class="beta-tag">SECUENCIA</span></div><button class="text-button" @click="addScene()"><Icon name="plus" :size="14" />Añadir escena</button></div><div class="timeline-content"><div class="transport"><button class="play-button" :aria-label="playing ? 'Pausar' : 'Reproducir'" @click="playing = !playing"><Icon :name="playing ? 'pause' : 'play'" :size="18" /></button><button class="icon-button" aria-label="Volver al inicio" @click="time = 0"><Icon name="reset" :size="15" /></button><span>{{ time.toFixed(1).padStart(4, '0') }}<small>/ {{ duration.toFixed(1) }} s</small></span></div><div class="timeline-track"><div class="timeline-ruler"><span v-for="tick in 6" :key="tick">{{ ((tick - 1) * timelineDuration / 5).toFixed(0).padStart(2, '0') }}s</span></div><div class="timeline-blocks"><div v-for="(block, index) in project.timeline" :key="block.id" :class="['timeline-block', { active: sequencing && scene.index === index }]" :style="{ flex: block.duration }"><button class="scene-main" @click="seekScene(index)"><Icon :name="MOTIONS.find(m => m.id === block.state)!.icon" :size="15" /><span>{{ MOTIONS.find(m => m.id === block.state)!.label }}</span></button><div class="scene-editor"><label><span class="visually-hidden">Duración de escena {{ index + 1 }}</span><input type="number" min="0.5" max="10" step="0.5" :value="block.duration" @change="sceneDuration(index, $event)" />s</label><div class="scene-controls"><button :disabled="index === 0" :aria-label="`Mover escena ${index + 1} antes`" @click="moveScene(index, -1)">‹</button><button :disabled="index === project.timeline.length - 1" :aria-label="`Mover escena ${index + 1} después`" @click="moveScene(index, 1)">›</button><button :disabled="project.timeline.length === 1" :aria-label="`Eliminar escena ${index + 1}`" @click="removeScene(index)">×</button></div></div></div></div><input class="timeline-scrubber" type="range" min="0" :max="duration - 0.001" step="0.01" :value="time" aria-label="Posición de reproducción" @input="event => { time = Number((event.target as HTMLInputElement).value); playing = false }" /></div></div><div class="timeline-bottom"><label class="toggle-label"><input v-model="sequencing" type="checkbox" @change="time = 0" />Reproducir secuencia</label><span><span class="orange-dot"></span>{{ reduced ? 'Movimiento reducido · reproducción manual' : 'Bucle continuo' }}</span></div></section>
        </div>

        <section v-else class="integration-layout"><div class="integration-intro"><span class="integration-symbol"><Icon name="code" :size="34" /></span><h2>Tu agente, donde lo necesites.</h2><p>Usa el componente Vue para conectar sus estados a tu producto, o descarga un SVG animado para insertarlo como una imagen.</p><div class="integration-actions"><button class="button primary" @click="downloadAnimation"><Icon name="download" :size="16" />SVG animado</button><button class="button" @click="downloadProject"><Icon name="download" :size="16" />Proyecto JSON</button></div><div class="integration-callout"><Icon name="layers" :size="20" /><div><strong>La composición viaja contigo.</strong><p>El JSON conserva los personajes, colores, expresiones, accesorios y toda la secuencia. Impórtalo para seguir editando.</p></div></div><a class="text-button" href="https://github.com/IvanCoronado/bloub/blob/codex/qamarero-agent-studio/docs/qamarero-studio.md" target="_blank" rel="noreferrer"><Icon name="book" :size="17" />Guía de integración<Icon name="external" :size="13" /></a></div><div class="code-card"><header><span>AgentAvatar.vue</span><button class="text-button" @click="copyCode"><Icon name="copy" :size="14" />Copiar</button></header><pre><code>{{ integrationCode }}</code></pre><div class="code-preview"><AgentAvatar :config="config" :time="time" :state="scene.state" :size="190" /><span>Vue 3 + TypeScript<span class="orange-dot"></span>SVG nativo</span></div></div></section>

        <footer class="page-footer"><span>Pequeños personajes. Grandes compañeros.</span><button class="text-button" @click="downloadProject"><Icon name="download" :size="13" />Descargar proyecto JSON</button></footer>
      </main>
    </div>
    <div v-if="message" class="studio-toast" role="status"><Icon name="sparkles" :size="17" />{{ message }}<button class="icon-button" aria-label="Cerrar aviso" @click="message = ''"><Icon name="close" :size="14" /></button></div>
    <ExportDialog v-if="exporting" :config="config" :state="scene.state" :time="scene.time" :timeline="sequencing ? project.timeline : undefined" @close="exporting = false" @done="notify" />
    <AgentPresentation v-if="presenting" embedded @close="presenting = false" />
  </div>
</template>
